<?php declare(strict_types=1);use FMonitor2\YiiRuntime\Assets\InstallerDirectoryAssetBundle;use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;
InstallerDirectoryAssetBundle::register($this);$choice=static fn($n,$v,$o,$l)=>ViewSupport::choice($n,$v,$o,$l);$return=http_build_query(['q'=>$filters['q'],'current'=>$filters['current'],'upcoming'=>$filters['upcoming'],'page'=>$filters['page']]);ViewSupport::begin($this,'Монтажники',$identity,'installers');?><main><div class="fm2-page-header"><div><h1>Монтажники</h1><p>Кадровый статус и действующие закрепления</p></div><span class="fm2-result-count"><?=(int)$filters['total']?> сотрудников</span></div>
<section class="fm2-directory-summary"><div><strong data-directory-summary="total"><?=(int)$summary['total']?></strong><span>Всего</span></div><div><strong data-directory-summary="working"><?=(int)$summary['working']?></strong><span>Работают</span></div><div><strong data-directory-summary="dismissed"><?=(int)$summary['dismissed']?></strong><span>Уволены</span></div><div><strong data-directory-summary="assigned"><?=(int)$summary['assigned']?></strong><span>Закреплены</span></div></section>
<section class="fm2-list-surface" data-filtered-count="<?=(int)$filters['total']?>"><form method="get" action="/pilot/installers" class="fm2-user-toolbar"><label class="shlz-field"><span class="shlz-field__label">Поиск</span><span class="shlz-field__control"><input class="shlz-input" type="search" name="q" maxlength="120" value="<?=Html::encode($filters['q'])?>"></span></label><?=$choice('status',$filters['status'],[''=>'Все','employed'=>'Работает','dismissed'=>'Уволен'],'Кадровый статус')?><?=$choice('availability',$filters['availability'],[''=>'Все','assigned'=>'Закреплён','free'=>'Свободен'],'Закрепление')?><?=$choice('current',$filters['current'],[''=>'Любая','present'=>'Есть','absent'=>'Нет'],'Текущая работа')?><?=$choice('upcoming',$filters['upcoming'],[''=>'Любое','present'=>'Есть','absent'=>'Нет'],'Предстоящее назначение')?><button class="shlz-button" type="submit">Показать</button></form>
<?php if($rows===[]):?><p class="shlz-table__empty"><?=(int)$summary['total']===0?'Каталог монтажников пока не загружен':'Ничего не найдено'?></p><?php else:?><div class="shlz-table-wrap fm2-installer-table-scroll"><table class="shlz-table fm2-installer-table"><thead><tr><th>Монтажник</th><th>Должность</th><th>Кадровый статус</th><th>Загрузка</th><th>Объекты</th></tr></thead><tbody>
<?php foreach($rows as$r):$count=(int)$r['currentWorkCount'];$work=$count===0?'Нет текущих работ':$count.' '.($count===1?'текущая работа':'текущие работы');?><tr data-installer-tab-id="<?=(int)$r['installer_tab_id']?>" data-current-work-count="<?=$count?>"><td><a class="shlz-link" href="/pilot/installers/<?=(int)$r['installer_tab_id']?>?return=<?=rawurlencode($return)?>"><strong><?=Html::encode($r['fio'])?></strong></a><small>таб. <?=str_pad((string)$r['installer_tab_id'],6,'0',STR_PAD_LEFT)?></small></td><td><?=Html::encode($r['position'])?></td><td><span class="shlz-status <?=$r['employment_status']==='employed'?'shlz-status--bright-green':'shlz-status--neutral'?>"><?=$r['employment_status']==='employed'?'Трудоустроен':'Уволен'?></span></td><td><?=$work?><?php if($r['upcomingAssignments']!==[]):?><small>Предстоящее назначение: <?=Html::encode($r['upcomingAssignments'][0]['registration_number'])?></small><?php endif?></td><td><?php $shown=[];foreach([...$r['assignments'],...$r['upcomingAssignments']]as$a):if(isset($shown[(int)$a['object_id']]))continue;$shown[(int)$a['object_id']]=true;?><a class="shlz-link fm2-assignment-link" href="/pilot/objects/<?=(int)$a['object_id']?>"><strong><?=Html::encode($a['registration_number'])?></strong><span><?=Html::encode($a['address'])?></span></a><?php endforeach?></td></tr><?php endforeach?></tbody></table></div><?php endif?><?=ViewSupport::pagination('/pilot/installers',(int)$filters['page'],(int)$filters['pages'],(int)$filters['total'],50,['q'=>$filters['q'],'status'=>$filters['status'],'availability'=>$filters['availability']],'Страницы монтажников')?></section></main><?php ViewSupport::end($this);
